transfer.sketch:
value Crop: id (blind), pixels, site, season, truth?   -- truth only for controls

gate(c) → keep | unknown
  if c.pixels < 40 or blur(c) > 0.6: return unknown     -- frozen; calibrated on held-out site-year
  return keep

batch = shuffle(keptCrops ++ stratify(historical, site, season, 40))
runs  = chunks(batch, 6)
s     = score(runs, controls) → { auc, brier, hi, lo, usableShare }

for v in verdicts of real crops:
  if v.p >= s.hi: accept(v.id, v.label)
  elif v.p <= s.lo: accept(v.id, empty)
  else: review.enqueue(v.id, showVerdict: false)      -- ranked by |p - boundary|
for v in randomSample(accepted, 0.10): review.enqueue(v.id, showVerdict: false)
-- if middle band > ~2000 per year: accept only its top-ranked slice, leave the rest unknown
